292: int arch_dup_task_struct(struct task_struct *dst, struct task_struct *src)
293: {
294: 	if (current->mm)
295: 		fpsimd_preserve_current_state();
296: 	*dst = *src;
297: 
298: 	/* We rely on the above assignment to initialize dst's thread_flags: */
299: 	BUILD_BUG_ON(!IS_ENABLED(CONFIG_THREAD_INFO_IN_TASK));
300: 
301: 	/*
302: 	 * Detach src's sve_state (if any) from dst so that it does not
303: 	 * get erroneously used or freed prematurely.  dst's copies
304: 	 * will be allocated on demand later on if dst uses SVE.
305: 	 * For consistency, also clear TIF_SVE here: this could be done
306: 	 * later in copy_process(), but to avoid tripping up future
307: 	 * maintainers it is best not to leave TIF flags and buffers in
308: 	 * an inconsistent state, even temporarily.
309: 	 */
310: 	dst->thread.sve_state = NULL;
311: 	clear_tsk_thread_flag(dst, TIF_SVE);
312: 
313: 	/*
314: 	 * In the unlikely event that we create a new thread with ZA
315: 	 * enabled we should retain the ZA state so duplicate it here.
316: 	 * This may be shortly freed if we exec() or if CLONE_SETTLS
317: 	 * but it's simpler to do it here. To avoid confusing the rest
318: 	 * of the code ensure that we have a sve_state allocated
319: 	 * whenever za_state is allocated.
320: 	 */
321: 	if (thread_za_enabled(&src->thread)) {
322: 		dst->thread.sve_state = kzalloc(sve_state_size(src),
323: 						GFP_KERNEL);
324: 		if (!dst->thread.za_state)
325: 			return -ENOMEM;
326: 		dst->thread.za_state = kmemdup(src->thread.za_state,
327: 					       za_state_size(src),
328: 					       GFP_KERNEL);
329: 		if (!dst->thread.za_state) {
330: 			kfree(dst->thread.sve_state);
331: 			dst->thread.sve_state = NULL;
332: 			return -ENOMEM;
333: 		}
334: 	} else {
335: 		dst->thread.za_state = NULL;
336: 		clear_tsk_thread_flag(dst, TIF_SME);
337: 	}
338: 
339: 	/* clear any pending asynchronous tag fault raised by the parent */
340: 	clear_tsk_thread_flag(dst, TIF_MTE_ASYNC_FAULT);
341: 
342: 	return 0;
343: }

